/* Original material effects and Korean voice clips. No commercial game recordings. */
const HodonSound=(()=>{
 const AUDIO_ASSETS={"bet-allin":"data:audio/mpeg;base64,","bet-call":"data:audio/mpeg;base64,","bet-check":"data:audio/mpeg;base64,","bet-ddang":"data:audio/mpeg;base64,","bet-double":"data:audio/mpeg;base64,","bet-fold":"data:audio/mpeg;base64,","bet-gwang":"data:audio/mpeg;base64,","bet-gwang38":"data:audio/mpeg;base64,","bet-half":"data:audio/mpeg;base64,","bet-quarter":"data:audio/mpeg;base64,","bet-small":"data:audio/mpeg;base64,","sfx-cash":"data:audio/mpeg;base64,","sfx-deal":"data:audio/mpeg;base64,","sfx-reveal":"data:audio/mpeg;base64,","sfx-slap":"data:audio/mpeg;base64,","sfx-squeeze":"data:audio/mpeg;base64,","voice-do":"data:audio/mpeg;base64,","voice-gae":"data:audio/mpeg;base64,","voice-geol":"data:audio/mpeg;base64,","voice-yut":"data:audio/mpeg;base64,","voice-mo":"data:audio/mpeg;base64,","voice-backdo":"data:audio/mpeg;base64,","sfx-yutthrow":"data:audio/mpeg;base64,"};
 const sampleLoads=new Map();let voiceEpoch=0;
 let ctx=null,master=null,noise=null,muted=localStorage.getItem('hodon:sound-muted')==='1';let volume=Number(localStorage.getItem('hodon:sound-volume')??40);if(!Number.isFinite(volume))volume=40;volume=Math.max(0,Math.min(100,volume));const seen=new Set(),voiceSeen=new Set(),voiceLoads=new Map();let currentVoice=null;
 function stopVoice(){voiceEpoch++;try{currentVoice?.stop()}catch{}currentVoice=null}
 function loadVoice(name){return loadSample('voice-'+name);}
 async function announceYut(steps,key){const name=({1:'do',2:'gae',3:'geol',4:'yut',5:'mo','-1':'backdo'})[steps];if(!name||muted||!volume||!ctx||document.hidden)return;if(key){if(voiceSeen.has(key))return;voiceSeen.add(key);if(voiceSeen.size>300)voiceSeen.delete(voiceSeen.values().next().value)}const buffer=await loadVoice(name);if(!buffer||muted||!volume||ctx.state!=='running'||document.hidden)return;stopVoice();const source=ctx.createBufferSource();source.buffer=buffer;source.connect(master);currentVoice=source;source.onended=()=>{if(currentVoice===source)currentVoice=null};source.start(ctx.currentTime+.48)}

 function loadSample(name){if(!AUDIO_ASSETS[name]||!ctx?.decodeAudioData)return Promise.resolve(null);if(!sampleLoads.has(name))sampleLoads.set(name,(async()=>{try{let bytes;if(typeof atob==='function'){const raw=atob(AUDIO_ASSETS[name].split(',')[1]);bytes=Uint8Array.from(raw,c=>c.charCodeAt(0)).buffer;}else if(typeof fetch==='function'){const r=await fetch(AUDIO_ASSETS[name]);bytes=await r.arrayBuffer();}else return null;return await ctx.decodeAudioData(bytes);}catch{return null}})());return sampleLoads.get(name);}
 async function material(name,delay=0){const buffer=await loadSample('sfx-'+name);if(!buffer||muted||!volume||ctx?.state!=='running'||document.hidden)return false;const source=ctx.createBufferSource(),trim=ctx.createGain();trim.gain.value=name==='cash'?.12:name==='yutthrow'?.90:1;source.buffer=buffer;source.connect(trim);trim.connect(master);source.start(ctx.currentTime+Math.max(0,delay));return true;}
 async function announceAction(name,key){if(!AUDIO_ASSETS['bet-'+name]||muted||!volume||!ctx||ctx.state!=='running'||document.hidden)return;if(key){if(voiceSeen.has(key))return;voiceSeen.add(key);if(voiceSeen.size>300)voiceSeen.delete(voiceSeen.values().next().value);}stopVoice();const epoch=voiceEpoch,buffer=await loadSample('bet-'+name);if(!buffer||epoch!==voiceEpoch||muted||!volume||ctx.state!=='running'||document.hidden)return;const source=ctx.createBufferSource();source.buffer=buffer;source.connect(master);currentVoice=source;source.onended=()=>{if(currentVoice===source)currentVoice=null};source.start(ctx.currentTime+.015);}
 function ui(){const toggle=document.getElementById('sound-toggle'),slider=document.getElementById('sound-volume');if(!toggle||!slider)return;toggle.textContent=muted?'🔇 소리 켜기':'🔊 음소거';toggle.setAttribute('aria-pressed',String(muted));slider.value=String(volume);document.getElementById('sound-value').textContent=volume+'%';document.getElementById('sound-summary').textContent=muted||volume===0?'🔇 효과음':'🔊 효과음';}
 function gain(){if(muted||volume===0)stopVoice();if(master&&ctx)master.gain.setTargetAtTime(muted?0:volume/100*.55,ctx.currentTime,.02);}
 async function unlock(){try{if(!ctx){const C=window.AudioContext||window.webkitAudioContext;if(!C)return;ctx=new C();master=ctx.createGain();master.connect(ctx.destination);noise=ctx.createBuffer(1,ctx.sampleRate*.3,ctx.sampleRate);const samples=noise.getChannelData(0);for(let i=0;i<samples.length;i++)samples[i]=Math.random()*2-1;gain();}if(ctx.state==='suspended')await ctx.resume();for(const n of ['do','gae','geol','yut','mo','backdo'])void loadVoice(n);for(const n of Object.keys(AUDIO_ASSETS))void loadSample(n);}catch{}}
 function tone(freq,time,duration=.09,level=.25,type='sine',end=freq){const o=ctx.createOscillator(),g=ctx.createGain();o.type=type;o.frequency.setValueAtTime(freq,time);o.frequency.exponentialRampToValueAtTime(Math.max(20,end),time+duration);g.gain.setValueAtTime(.001,time);g.gain.exponentialRampToValueAtTime(Math.max(.002,level),time+.006);g.gain.exponentialRampToValueAtTime(.001,time+duration);o.connect(g);g.connect(master);o.start(time);o.stop(time+duration+.01);}
 function tap(time,duration=.08,freq=1800,level=.4){const s=ctx.createBufferSource(),filter=ctx.createBiquadFilter(),g=ctx.createGain();s.buffer=noise;filter.type='bandpass';filter.frequency.value=freq;g.gain.setValueAtTime(level,time);g.gain.exponentialRampToValueAtTime(.001,time+duration);s.connect(filter);filter.connect(g);g.connect(master);s.start(time);s.stop(time+duration);}
 // Modal wooden-piece impact: a short contact transient and damped body resonances.
 const alkWoodBuffers=[];
 function alkWood(t,level=.38){
  if(!ctx||!master)return;
  if(!alkWoodBuffers.length)for(let v=0;v<4;v++){
   const rate=ctx.sampleRate,duration=.17,buffer=ctx.createBuffer(1,Math.floor(rate*duration),rate),a=buffer.getChannelData(0),pitch=1+(v-1.5)*.045;let lp=0;
   for(let i=0;i<a.length;i++){const x=i/rate,noise=Math.random()*2-1;lp=.58*lp+.42*noise;const body=[[570,.5,.031],[1080,.3,.021],[1790,.16,.014],[2820,.07,.009]].reduce((sum,[f,amp,decay])=>sum+Math.sin(2*Math.PI*f*pitch*x)*amp*Math.exp(-x/decay),0);a[i]=Math.tanh((body+lp*.68*Math.exp(-x/.006))*1.2)*.7;}
   alkWoodBuffers.push(buffer);
  }
  const source=ctx.createBufferSource(),trim=ctx.createGain();source.buffer=alkWoodBuffers[Math.floor(Math.random()*alkWoodBuffers.length)];trim.gain.value=level;source.connect(trim);trim.connect(master);source.start(t);
 }
 function play(kind,key){if(key){if(seen.has(key))return;seen.add(key);if(seen.size>300)seen.delete(seen.values().next().value);}if(muted||volume===0||!ctx||ctx.state!=='running'||document.hidden)return;try{const t=ctx.currentTime+.01;const sample=({throw:'yutthrow',deal:'deal',chips:'cash',cash:'cash',fold:'deal',replay:'deal',squeeze:'squeeze',slap:'slap',reveal:'reveal','table-win':'cash'})[kind];if(sample)return material(sample);
  if(kind==='alk-hit'){alkWood(t,.52);}
  else if(kind==='alk-drop'){alkWood(t,.24);alkWood(t+.055,.12);}
  else if(kind==='alk-turn'||kind==='alk-turn-self'){alkWood(t,.15);tone(kind==='alk-turn-self'?587:440,t+.07,.19,.10,'sine');tone(kind==='alk-turn-self'?784:587,t+.20,.22,.07,'sine');}
  else if(/^countdown-[1-5]$/.test(kind)){const n=Number(kind.slice(-1));tone(n<=2?930:650,t,.065,n===1?.16:.10,'sine');tap(t,.025,1900,.08);}
  else if(kind==='hand-victory'){[392,523.25,659.25].forEach((f,i)=>tone(f,t+i*.065,.23,.13,'sine'));void material('cash',.18);}
  else if(kind==='win'){[523.25,659.25,783.99,1046.5].forEach((f,i)=>tone(f,t+i*.13,.32,.18,'triangle'));[523.25,659.25,783.99].forEach(f=>tone(f,t+.57,.6,.12,'sine'));}
  else if(kind==='stone'){tap(t,.05,1700,.5);tone(950,t,.08,.18,'sine',420);}
  else if(kind==='move'){tap(t,.06,900,.32);tone(430,t,.08,.22,'triangle',180);}
  else if(kind==='capture'){tap(t,.1,2200,.4);[587,784,1175].forEach((f,i)=>tone(f,t+i*.08,.18,.2,'triangle'));}
  else if(kind==='replay'){[440,554,440].forEach((f,i)=>tone(f,t+i*.12,.14,.17,'triangle'));}
  else tone(680,t,.045,.1,'sine',820);
 }catch{}}
 document.addEventListener('pointerdown',unlock,{capture:true});document.addEventListener('keydown',unlock,{capture:true});
 document.getElementById('sound-toggle')?.addEventListener('click',async()=>{muted=!muted;localStorage.setItem('hodon:sound-muted',muted?'1':'0');gain();ui();await unlock();if(!muted)play('select');});
 document.getElementById('sound-volume')?.addEventListener('input',e=>{volume=Number(e.target.value);localStorage.setItem('hodon:sound-volume',String(volume));gain();ui();});
 document.getElementById('sound-test')?.addEventListener('click',async()=>{await unlock();play('reveal');});
 document.getElementById('sound-voice-test')?.addEventListener('click',async()=>{await unlock();await announceYut(1)});
 document.getElementById('sound-bet-voice-test')?.addEventListener('click',async()=>{await unlock();await announceAction('half');});
 document.addEventListener('visibilitychange',()=>{if(document.hidden){stopVoice();if(ctx?.state==='running')ctx.suspend().catch(()=>{});}});ui();return {play,unlock,announceYut,announceAction};
})();
